extern int far MapPnt[2];
extern int far VA;
extern int far VB;
extern int far MeLocX;
extern int far MeLocY;
extern int far MeType;
extern int far MeNest;
extern void far g(int);

variants.n_in_dead_or:
void far f(void)
{
    int n, x, y;

    n = 5;
    if (MeType == 0x40 && MeNest == 0)
        n = 2;
    x = MapPnt[0] + VA;
    if (x < MeLocX)
        x = MeLocX;
    if (MapPnt[1] + 2 > MeLocY || MeLocY - VB < n)
        y = x;
    g(1);
}

variants.n_in_dead_body:
void far f(void)
{
    int n, x, y;

    n = 5;
    if (MeType == 0x40 && MeNest == 0)
        n = 2;
    x = MapPnt[0] + VA;
    if (x < MeLocX)
        x = MeLocX;
    if (MapPnt[1] + 2 > MeLocY)
        y = MeLocY - n;
    g(1);
}
